		if (!received) { errors.push({ field: 'received', he: 'מתי קיבלתם את השומה? לדוגמה: 1.10.2026' }); }
		if (mine !== null && !(mine >= 0 && mine < 1e10)) { errors.push({ field: 'mine', he: 'ההיטל לפי השמאי שלכם: מספר 0 או יותר' }); }
